    90  /**
    91   * asn1_get_length_der:
    92   * @der: DER data to decode.
    93   * @der_len: Length of DER data to decode.
    94   * @len: Output variable containing the length of the DER length field.
    95   *
    96   * Extract a length field from DER data.
    97   *
    98   * Returns: Return the decoded length value, or -1 on indefinite
    99   *   length, or -2 when the value was too big to fit in a int, or -4
   100   *   when the decoded length value plus @len would exceed @der_len.
   101   **/
   102  long
   103  asn1_get_length_der (const unsigned char *der, int der_len, int *len)
   104  {
   105    unsigned int ans;
   106    int k, punt, sum;
   107
   108    *len = 0;
   109    if (der_len <= 0)
   110      return 0;
   111
   112    if (!(der[0] & 128))
   113      {
   114        /* short form */
   115        *len = 1;
   116        ans = der[0];
   117      }
   118    else
   119      {
   120        /* Long form */
   121        k = der[0] & 0x7F;
   122        punt = 1;
   123        if (k)
   124          { /* definite length method */
   125            ans = 0;
   126            while (punt <= k && punt < der_len)
   127              {
   128                if (INT_MULTIPLY_OVERFLOW (ans, 256))
   129                  return -2;
   130                ans *= 256;
   131
   132                if (INT_ADD_OVERFLOW (ans, ((unsigned) der[punt])))
   133                  return -2;
   134                ans += der[punt];
   135                punt++;
   136              }
   137          }
   138        else
   139          {                       /* indefinite length method */
   140            *len = punt;
   141            return -1;
   142          }
   143
   144        *len = punt;
   145      }
   146
   147    sum = ans;
   148    if (ans >= INT_MAX || INT_ADD_OVERFLOW (sum, (*len)))
   149      return -2;
   150    sum += *len;
